<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Student extends Model{protected $fillable=['department_id','teacher_id','name','slug','class_name','instrument','photo','bio','sort','is_active','is_public'];protected $casts=['is_active'=>'boolean','is_public'=>'boolean'];public function department(){return $this->belongsTo(Department::class);}public function teacher(){return $this->belongsTo(Teacher::class);}public function performances(){return $this->hasMany(EventPerformance::class)->where('is_published',true)->with(['event','media','teacher'])->whereHas('event',fn($q)=>$q->where('is_published',true))->getQuery();}public function getRouteKeyName(){return 'slug';}}